log = []

def step(name, fail=False):
    def do():
        if fail:
            raise RuntimeError(f"{name} failed")
        log.append(f"do {name}")
    def undo():
        log.append(f"undo {name}")
    return name, do, undo

saga = [step("reserve_stock"), step("charge_card"), step("create_shipment", fail=True)]
done = []
try:
    for name, do, undo in saga:
        do()
        done.append(undo)
except RuntimeError as e:
    log.append(str(e))
    for undo in reversed(done):
        undo()
print("\n".join(log))

import requests

def dashboard(seller_id):
    seller = requests.get(f"http://catalog/sellers/{seller_id}").json()
    prices = requests.get(f"http://pricing/sellers/{seller_id}/prices").json()
    stock = requests.get(f"http://inventory/sellers/{seller_id}").json()
    return {"seller": seller, "prices": prices, "stock": stock}
